def ReturnToDroneBay(droneIDs):
    entity = eveMoniker.GetEntityAccess()
    if entity:
        ret = entity.CmdReturnBay(droneIDs)
        HandleMultipleCallError(droneIDs, ret, 'MultiDroneCmdResult')
    return

def GetInventoryLocationID(self):
    inventoryLocationID, _ = self.invID
    return inventoryLocationID

def GetContractProxySvc(self):
    if self.contractProxySvc == None:
        self.contractProxySvc = sm.ProxySvc('contractProxy')
    return self.contractProxySvc

def _GetMovementDistanceOrDefault(targetID, targetRange, action, **kwargs):
    if targetRange is None:
        return GetDefaultDist(action, targetID, **kwargs)
    return targetRange

def IsValidArc(self, epicArcID):
    arcRestartInterval = get_epic_arc_restart_interval(epicArcID)
    return arcRestartInterval > 1

def is_expired(self):
    if not self.expiration_time:
        return False
    return self.expiration_time - blue.os.GetWallclockTime() < 0
